<?php
require __DIR__.'/../app/bootstrap.php';$u=require_seller();$a=application((int)$u['id']);$title='Seller overview';
$total=(int)q('SELECT COUNT(*) FROM menu_items WHERE seller_id=?',[$u['id']])->fetchColumn();
$live=(int)q("SELECT COUNT(*) FROM menu_items m JOIN categories c ON c.id=m.category_id WHERE m.seller_id=? AND ".live_sql('m')." AND c.active=1",[$u['id']])->fetchColumn();
$expired=count(array_filter(all('SELECT * FROM menu_items WHERE seller_id=?',[$u['id']]),fn($dish)=>menu_state($dish)==='Expired'));
$days=[];for($i=6;$i>=0;$i--){$day=(new DateTimeImmutable('today',new DateTimeZone(cfg('timezone'))))->modify("-$i days");$start=$day->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$end=$day->modify('+1 day')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$days[]=['label'=>$day->format('D'),'count'=>(int)q('SELECT COUNT(*) FROM menu_items WHERE seller_id=? AND created_at>=? AND created_at<?',[$u['id'],$start,$end])->fetchColumn()];}
$peak=max(1,...array_column($days,'count'));$recent=all('SELECT * FROM menu_items WHERE seller_id=? ORDER BY id DESC LIMIT 5',[$u['id']]);require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><span class="heading-kicker">YOUR SELLER WORKSPACE</span><h1>Hello, <?=e($a['business_name'])?> 👋</h1><p class="dash-sub">A fresh look at what’s cooking in your kitchen.</p></div><a class="pill primary" href="<?=e(url('seller/menu-create.php'))?>">＋ Add menu item</a></div><div class="metrics three"><?php foreach([['All menu items',$total,'Your complete menu'],['Live dishes',$live,'Visible to customers now'],['Expired dishes',$expired,'Automatically hidden']] as [$label,$n,$sub]): ?><div class="metric"><div class="metric-icon">✦</div><div class="metric-label"><?=e($label)?></div><div class="metric-value"><?=$n?></div><div class="metric-foot"><?=e($sub)?></div></div><?php endforeach ?></div>
<div class="dash-grid"><section class="panel"><div class="panel-top"><h2>Menu additions</h2><small>Last 7 days</small></div><div class="bars" role="img" aria-label="Daily menu additions: <?=e(implode(', ',array_map(fn($d)=>$d['label'].' '.$d['count'],$days)))?>"><?php foreach($days as $d): ?><div class="bar-set"><div class="bar dark" style="height:<?=max(1,round($d['count']/$peak*90))?>%"><span class="bar-number"><?=$d['count']?></span></div><span class="bar-label"><?=e($d['label'])?></span></div><?php endforeach ?></div><p class="hint space-top">Actual menu items created each day · <?=e(cfg('timezone'))?></p></section><section class="panel lavender"><span class="heading-kicker">KEEP IT FRESH</span><h2>Your menu, on your schedule.</h2><p>Set an expiry for every dish. Once the time is up, it disappears from customer listings automatically.</p><a class="pill" href="<?=e(url('seller/menu.php'))?>">Manage my menu →</a><p class="hint">Sales, order and revenue analytics will be added when checkout is built.</p></section></div>
<section class="panel list-panel"><div class="panel-top"><h2>Recent dishes</h2><a href="<?=e(url('seller/menu.php'))?>">View all →</a></div><?php if(!$recent): ?><p class="empty">Your menu starts here. Add your first dish.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Dish</th><th>Price</th><th>Available until</th></tr></thead><tbody><?php foreach($recent as $m): ?><tr><td><a href="<?=e(url('seller/menu-edit.php?id='.$m['id']))?>"><?=e($m['name'])?></a></td><td>Rs <?=number_format($m['price_paisa']/100,2)?></td><td><?=e(local_time(live_until($m)))?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
